import sys

# Increase integer string conversion limit if needed, though arithmetic has no limit.
sys.set_int_max_str_digits(100000)


def calc(expr: str) -> int | str:
    class CalcError(Exception):
        pass

    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            tokens.append(("NUM", int(expr[start:i])))
        elif c in "+-*/%^()":
            tokens.append((c, c))
            i += 1
        else:
            i += 1

    pos = 0
    num_tokens = len(tokens)

    def peek():
        if pos < num_tokens:
            return tokens[pos]
        return (None, None)

    # Grammar based on precedence:
    # expr -> term_add
    # term_add -> term_mul ( ('+' | '-') term_mul )*   [left-associative]
    # term_mul -> unary ( ('*' | '/' | '%') unary )*    [left-associative]
    # unary -> '-' unary | power
    # Note on precedence:
    # 1. ^ (power), right-associative: 2^3^2 = 2^(3^2).
    # 2. Unary minus binds looser than ^: -2^2 is -(2^2).
    #    "The right operand of ^ may start with a unary minus: 2^-1 is 2^(-1)."
    #    So power's base is primary (literal or parenthesized expression).
    #    power -> base ('^' power_rhs)?
    #    where power_rhs can be a unary expression!
    #    Wait: if power_rhs is unary, 2^-3^2:
    #    unary minus on RHS: 2^(-(3^2)) = 2^-9?
    #    Let's check: "The right operand of ^ may start with a unary minus: 2^-1 is 2^(-1)."
    #    In 2^3^2, right operand of the first ^ is 3^2.
    #    If power_rhs is unary, then:
    #    power_rhs -> unary (which handles '-' unary | power).
    #    So base '^' unary:
    #    For 2^3^2: base 2, operator '^', power_rhs is unary -> power -> base 3 '^' unary...
    #    For 2^-1: base 2, operator '^', power_rhs is unary -> '-' unary -> 1.
    #    For -2^2: unary -> '-' unary -> power(2^2) -> -4.
    #    Everything matches the specification perfectly!

    def parse_expr():
        return parse_add()

    def parse_add():
        nonlocal pos
        val = parse_mul()
        while pos < num_tokens and tokens[pos][0] in ("+", "-"):
            op = tokens[pos][0]
            pos += 1
            r = parse_mul()
            if op == "+":
                val = val + r
            else:
                val = val - r
        return val

    def parse_mul():
        nonlocal pos
        val = parse_unary()
        while pos < num_tokens and tokens[pos][0] in ("*", "/", "%"):
            op = tokens[pos][0]
            pos += 1
            r = parse_unary()
            if op == "*":
                val = val * r
            elif op == "/":
                if r == 0:
                    raise CalcError()
                # Truncate toward zero: int(a / b) in Python can lose precision for huge ints.
                # Exact integer division truncating toward zero:
                if (val >= 0 and r > 0) or (val <= 0 and r < 0):
                    val = abs(val) // abs(r)
                else:
                    val = -(abs(val) // abs(r))
            elif op == "%":
                if r == 0:
                    raise CalcError()
                # a % b is a - b * (a / b), using truncating /
                if (val >= 0 and r > 0) or (val <= 0 and r < 0):
                    q = abs(val) // abs(r)
                else:
                    q = -(abs(val) // abs(r))
                val = val - r * q
        return val

    def parse_unary():
        nonlocal pos
        if pos < num_tokens and tokens[pos][0] == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_primary()
        if pos < num_tokens and tokens[pos][0] == "^":
            pos += 1
            # Right-associative; right operand can start with unary minus
            exp = parse_unary()
            if exp < 0:
                raise CalcError()
            val = pow(base, exp)
            return val
        return base

    def parse_primary():
        nonlocal pos
        tok_type, tok_val = tokens[pos]
        if tok_type == "NUM":
            pos += 1
            return tok_val
        elif tok_type == "(":
            pos += 1
            val = parse_expr()
            pos += 1  # skip ')'
            return val
        raise CalcError()

    try:
        res = parse_expr()
        return res
    except (CalcError, RecursionError):
        return "error"
